const body = $json.body;
const gerarNovo = body.gerarNovo === true;
const textosAtuais = body.contexto?.textos_atuais || {};

return {
  json: {
    ...body,
    gerarNovo,
    textosAtuais
  }
};

const RESPONSABILIZACAO_PADRAO = `Declaramos que a despesa objeto da presente solicitação será efetivamente executada no exercício financeiro vigente, com a correspondente liquidação e pagamento previstos para ocorrer dentro do respectivo exercício.
Declaramos que a parcela correspondente aos exercícios subsequentes será alocada nas respectivas leis orçamentárias.
Responsabilizo-me, por fim, pelas informações prestadas, sob pena de prática do crime previsto no art. 299, caput e parágrafo único, do Código Penal, e ato de improbidade administrativa, nos termos do art. 10, incisos IX e XI, da Lei Federal nº 8.429, de 2 de junho de 1992, sem prejuízo das demais sanções penais, administrativas e cíveis cabíveis.`;

return {
  json: {
    esgotamento: $json.textosAtuais.esgotamento || '',
    justificativa_despesa: $json.textosAtuais.justificativa_despesa || '',
    responsabilizacao: RESPONSABILIZACAO_PADRAO
  }
};

let raw = $json.text ?? $json.output ?? $json.content ?? '';
raw = raw.trim();

if (raw.startsWith('```')) {
  raw = raw.replace(/^```json\s*/i, '').replace(/```$/, '').trim();
}

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  throw new Error('IA não retornou JSON válido: ' + raw);
}

const RESPONSABILIZACAO_PADRAO = `Declaramos que a despesa objeto da presente solicitação será efetivamente executada no exercício financeiro vigente, com a correspondente liquidação e pagamento previstos para ocorrer dentro do respectivo exercício.
Declaramos que a parcela correspondente aos exercícios subsequentes será alocada nas respectivas leis orçamentárias.
Responsabilizo-me, por fim, pelas informações prestadas, sob pena de prática do crime previsto no art. 299, caput e parágrafo único, do Código Penal, e ato de improbidade administrativa, nos termos do art. 10, incisos IX e XI, da Lei Federal nº 8.429, de 2 de junho de 1992, sem prejuízo das demais sanções penais, administrativas e cíveis cabíveis.`;

return {
  json: {
    esgotamento: parsed.esgotamento || '',
    justificativa_despesa: parsed.justificativa_despesa || '',
    responsabilizacao: RESPONSABILIZACAO_PADRAO
  }
};
